python3 -c 'import mpmath as m,pathlib,json;P=pathlib.Path("Riemann_Quine_OneLiner.sh").read_bytes();E=lambda b:int.from_bytes(b"\1"+b,"big");D=lambda n:n.to_bytes((n.bit_length()+7)//8,"big")[1:];e=E(P);r=e%1000003;t=14+30*r/1000003;m.mp.dps=60;s=m.mpc(.5,t);z=m.zeta(s);print(json.dumps({"self":hex(e),"X":["0.5",m.nstr(t,50)],"Y":[m.nstr(m.re(z),50),m.nstr(m.im(z),50)],"source":P.decode(),"source_recovered":D(e)==P,"program_equals_zeta":False,"analytic_fixed_point_claimed":False,"open":True,"final":False},separators=(",",":")))'